local repo = 'https://raw.githubusercontent.com/KingScriptAE/No-sirve-nada./refs/heads/main/'
local Library = loadstring(game:HttpGet(repo .. 'Library.lua'))()
local ThemeManager = loadstring(game:HttpGet(repo .. 'addons/ThemeManager.lua'))()
local SaveManager = loadstring(game:HttpGet(repo .. 'addons/SaveManager.lua'))()
local Options = Library.Options

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local localPlayer = Players.LocalPlayer
local playerGui = localPlayer:WaitForChild("PlayerGui")
local MainGui = playerGui:WaitForChild("MainGui")
-- KeyAuth.cc 鉴权 【重型钓鱼】
local HttpService = game:GetService("HttpService")
local name = "重型钓鱼"
local ownerid = "w2xCygqaOQ"
local version = "1.0"
local apiUrl = "https://keyauth.cc/api/1/"

-- 弹窗输入密钥（复用你UI库的PromptInput）
local userKey = Library:PromptInput("重型钓鱼｜请输入密钥","粘贴你的KeyAuth密钥")
if not userKey or userKey == "" then
    Library:Notify("❌密钥不能为空，脚本退出")
    return
end

local function KeyAuthCheck(key)
    local body = HttpService:JSONEncode({
        name = name,
        ownerid = ownerid,
        version = version,
        key = key
    })
    local ok,resp = pcall(function()
        return game:HttpPost(apiUrl, body)
    end)
    if not ok then
        return false, "网络请求失败:"..tostring(resp)
    end
    local decodeOk,data = pcall(function() return HttpService:JSONDecode(resp) end)
    if not decodeOk then
        return false,"服务器返回数据异常"
    end
    if data.success then
        return true, data.message
    else
        return false, data.message
    end
end

local pass,msg = KeyAuthCheck(userKey)
if pass then
    Library:Notify("✅鉴权成功："..msg)
else
    Library:Notify("❌鉴权失败："..msg)
    return
end

